 1→import { NextRequest, NextResponse } from 'next/server';
 2→
 3→const BACKEND_URL = process.env.BACKEND_URL || 'http://localhost:8080';
 4→
 5→export async function GET(
 6→  request: NextRequest,
 7→  { params }: { params: Promise<{ path: string[] }> }
 8→) {
 9→  const { path } = await params;
10→  const targetPath = path.join('/');
11→  const searchParams = request.nextUrl.searchParams.toString();
12→  const url = `${BACKEND_URL}/api/${targetPath}${searchParams ? `?${searchParams}` : ''}`;
13→
14→  const response = await fetch(url, {
15→    headers: {
16→      'Content-Type': 'application/json',
17→    },
18→  });
19→
20→  const data = await response.json();
21→  return NextResponse.json(data, { status: response.status });
22→}
23→
24→export async function POST(
25→  request: NextRequest,
26→  { params }: { params: Promise<{ path: string[] }> }
27→) {
28→  const { path } = await params;
29→  const targetPath = path.join('/');
30→  const url = `${BACKEND_URL}/api/${targetPath}`;
31→  const body = await request.json().catch(() => ({}));
32→
33→  const response = await fetch(url, {
34→    method: 'POST',
35→    headers: {
36→      'Content-Type': 'application/json',
37→    },
38→    body: JSON.stringify(body),
39→  });
40→
41→  const data = await response.json().catch(() => ({}));
42→  return NextResponse.json(data, { status: response.status });
43→}
44→
45→export async function PUT(
46→  request: NextRequest,
47→  { params }: { params: Promise<{ path: string[] }> }
48→) {
49→  const { path } = await params;
50→  const targetPath = path.join('/');
51→  const url = `${BACKEND_URL}/api/${targetPath}`;
52→  const body = await request.json().catch(() => ({}));
53→
54→  const response = await fetch(url, {
55→    method: 'PUT',
56→    headers: {
57→      'Content-Type': 'application/json',
58→    },
59→    body: JSON.stringify(body),
60→  });
61→
62→  const data = await response.json().catch(() => ({}));
63→  return NextResponse.json(data, { status: response.status });
64→}
65→
66→export async function DELETE(
67→  request: NextRequest,
68→  { params }: { params: Promise<{ path: string[] }> }
69→) {
70→  const { path } = await params;
71→  const targetPath = path.join('/');
72→  const url = `${BACKEND_URL}/api/${targetPath}`;
73→
74→  const response = await fetch(url, {
75→    method: 'DELETE',
76→    headers: {
77→      'Content-Type': 'application/json',
78→    },
79→  });
80→
81→  if (response.status === 204) {
82→    return new NextResponse(null, { status: 204 });
83→  }
84→
85→  const data = await response.json().catch(() => ({}));
86→  return NextResponse.json(data, { status: response.status });
87→}
