45→export async function PUT(
46→  request: NextRequest,
47→  { params }: { params: Promise<{ path: string[] }> }
48→) {
49→  const { path } = await params;
50→  const targetPath = path.join('/');
51→  const url = `${BACKEND_URL}/api/${targetPath}`;
52→  const body = await request.json().catch(() => ({}));
53→
54→  const response = await fetch(url, {
55→    method: 'PUT',
56→    headers: {
57→      'Content-Type': 'application/json',
58→    },
59→    body: JSON.stringify(body),
60→  });
61→
62→  const data = await response.json().catch(() => ({}));
63→  return NextResponse.json(data, { status: response.status });
64→}
65→
66→export async function DELETE(
67→  request: NextRequest,
68→  { params }: { params: Promise<{ path: string[] }> }
69→) {
70→  const { path } = await params;
71→  const targetPath = path.join('/');
72→  const url = `${BACKEND_URL}/api/${targetPath}`;
73→
74→  const response = await fetch(url, {
