 3→import { useGetDictionariesQuery, type DictionaryFindInput, type DictionaryPageInput } from '@/generated/real-hooks'
 4→import { DictionaryItem } from '@/views/dictionary-manage/model/type'
 5→import { mapDictionariesToItems } from './mapper'
 6→
 7→export const useDictionaries = (
 8→    input?: DictionaryFindInput,
 9→    page?: DictionaryPageInput,
10→    options?: { skip?: boolean; fetchPolicy?: WatchQueryFetchPolicy }
11→) => {
12→    const queryResult = useGetDictionariesQuery({
13→        variables: { input, page },
14→        skip: options?.skip,
15→        fetchPolicy: options?.fetchPolicy ?? 'network-only'
16→    })
17→
18→    const transformedData = useMemo(() => {
19→        if (!queryResult.data?.dictionaries?.items) {
20→            return {
21→                items: [] as DictionaryItem[],
22→                pageInfo: queryResult.data?.dictionaries?.pageInfo
23→            }
24→        }
25→
26→        const items = mapDictionariesToItems(queryResult.data.dictionaries.items)
27→
28→        return {
29→            items,
30→            pageInfo: queryResult.data.dictionaries.pageInfo
31→        }
32→    }, [queryResult.data])
33→
34→    return {
35→        ...queryResult,
36→        data: transformedData
37→    }
